@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-dm-sans);
  --font-cooper: var(--font-cooper);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-control: var(--control);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-success-tint: var(--success-tint);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-warning-tint: var(--warning-tint);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --color-link: var(--link);
  --color-link-hover: var(--link-hover);
  --radius-sm: calc(var(--radius) - 2px);
  --radius-md: var(--radius);
  --radius-lg: calc(var(--radius) + 4px);
  --radius-xl: calc(var(--radius) + 8px);
  --radius-2xl: calc(var(--radius) + 12px);
  --radius-3xl: calc(var(--radius) + 16px);
  --radius-4xl: calc(var(--radius) + 20px);

  --color-primary-hover: var(--primary-hover);
  --color-accent-hover: var(--accent-hover);
  --color-emblem: var(--emblem);

  --color-pine-50: hsla(160, 30%, 96%, 1);
  --color-pine-100: hsla(164, 48%, 77%, 1);
  --color-pine-200: hsla(166, 33%, 65%, 1);
  --color-pine-300: hsla(166, 26%, 55%, 1);
  --color-pine-400: hsla(167, 35%, 36%, 1);
  --color-pine-500: hsla(169, 54%, 27%, 1);
  --color-pine-600: hsla(170, 100%, 16%, 1);
  --color-pine-700: hsla(170, 90%, 11%, 1);
  --color-pine-800: hsla(168, 94%, 6%, 1);
  --color-pine-900: hsla(168, 94%, 5%, 1);
  --color-pine-950: hsla(168, 95%, 3.5%, 1);

  --color-neutral-50: hsla(0, 0%, 95%, 1);
  --color-neutral-100: hsla(0, 0%, 83%, 1);
  --color-neutral-200: hsla(0, 0%, 73%, 1);
  --color-neutral-300: hsla(169, 8%, 60%, 1);
  --color-neutral-400: hsla(169, 8%, 44%, 1);
  --color-neutral-500: hsla(170, 10%, 35%, 1);
  --color-neutral-600: hsla(168, 11%, 26%, 1);
  --color-neutral-700: hsla(170, 13%, 18%, 1);
  --color-neutral-800: hsla(173, 18%, 10%, 1);
  --color-neutral-900: hsla(0, 0%, 0%, 1);

  --color-crimson-50: hsla(356, 89%, 96%, 1);
  --color-crimson-100: hsla(356, 86%, 88%, 1);
  --color-crimson-200: hsla(355, 73%, 79%, 1);
  --color-crimson-300: hsla(355, 47%, 68%, 1);
  --color-crimson-400: hsla(355, 29%, 51%, 1);
  --color-crimson-500: hsla(354, 34%, 43%, 1);
  --color-crimson-600: hsla(354, 50%, 30%, 1);
  --color-crimson-700: hsla(352, 70%, 22%, 1);
  --color-crimson-800: hsla(352, 100%, 13%, 1);
  --color-crimson-900: hsla(352, 55%, 6.5%, 1);
  --color-crimson-950: hsla(352, 60%, 4.5%, 1);
}

:root {
  --radius: 0.5rem;

  /* Light Mode (New Brand Colors) */
  --background: #ffffff;
  --foreground: hsla(168, 94%, 6%, 1);

  --card: #ffffff;
  --card-foreground: hsla(168, 94%, 6%, 1);

  --popover: #ffffff;
  --popover-foreground: hsla(168, 94%, 6%, 1);

  --primary: hsla(170, 100%, 16%, 1);
  --primary-foreground: #ffffff;
  --primary-hover: hsla(170, 90%, 11%, 1);

  --secondary: hsla(0, 0%, 95%, 1);
  --secondary-foreground: hsla(168, 94%, 6%, 1);

  --muted: hsla(0, 0%, 95%, 1);
  --muted-foreground: hsla(170, 10%, 35%, 1);

  --accent: hsla(354, 34%, 43%, 1);
  --accent-foreground: #ffffff;
  --accent-hover: hsla(354, 50%, 30%, 1);

  --destructive: #ef4444;
  --destructive-foreground: #ffffff;

  --border: hsla(0, 0%, 83%, 1);
  --line: hsla(0, 0%, 88%, 1);
  --line-strong: hsla(0, 0%, 75%, 1);
  --control: hsla(0, 0%, 65%, 1);
  --input: hsla(0, 0%, 83%, 1);
  --ring: hsla(170, 100%, 16%, 1);

  --success: hsla(160, 84%, 39%, 1);
  --success-foreground: #ffffff;
  --success-tint: hsla(160, 60%, 95%, 1);
  --warning: hsla(38, 92%, 50%, 1);
  --warning-foreground: #ffffff;
  --warning-tint: hsla(38, 90%, 95%, 1);

  /* Link & Interactive Inks (Pine 600 - 7.5:1 AAA on white) */
  --link: hsla(170, 100%, 16%, 1);
  --link-hover: hsla(170, 90%, 11%, 1);
  --link-decoration: hsla(170, 100%, 16%, 0.4);

  --emblem: hsla(170, 90%, 11%, 1); /* Deep Pine 700 */

  --chart-1: hsla(170, 100%, 16%, 1);
  --chart-2: hsla(354, 34%, 43%, 1);
  --chart-3: hsla(169, 54%, 27%, 1);
  --chart-4: hsla(166, 33%, 65%, 1);
  --chart-5: hsla(355, 73%, 79%, 1);

  --sidebar: hsla(160, 30%, 96%, 1);
  --sidebar-foreground: hsla(168, 94%, 6%, 1);
  --sidebar-primary: hsla(170, 100%, 16%, 1);
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: hsla(0, 0%, 95%, 1);
  --sidebar-accent-foreground: hsla(168, 94%, 6%, 1);
  --sidebar-border: hsla(0, 0%, 83%, 1);
  --sidebar-ring: hsla(170, 100%, 16%, 1);
}

.dark {
  /* Dark Mode (Midnight Forest) */
  --background: hsla(168, 94%, 6%, 1);
  --foreground: hsla(0, 0%, 95%, 1);

  --card: hsla(170, 90%, 11%, 1);
  --card-foreground: hsla(0, 0%, 95%, 1);

  --popover: hsla(170, 90%, 11%, 1);
  --popover-foreground: hsla(0, 0%, 95%, 1);

  --primary: hsla(170, 100%, 16%, 1);
  --primary-foreground: #ffffff;
  --primary-hover: hsla(170, 90%, 11%, 1);

  --secondary: hsla(170, 13%, 18%, 1);
  --secondary-foreground: hsla(0, 0%, 95%, 1);

  --muted: hsla(170, 13%, 18%, 1);
  --muted-foreground: hsla(169, 8%, 60%, 1);

  --accent: hsla(354, 34%, 43%, 1);
  --accent-foreground: #ffffff;
  --accent-hover: hsla(354, 50%, 30%, 1);

  --destructive: #ef4444;
  --destructive-foreground: #ffffff;

  --border: hsla(168, 11%, 26%, 1);
  --line: hsla(168, 15%, 18%, 1);
  --line-strong: hsla(168, 12%, 28%, 1);
  --control: hsla(168, 10%, 42%, 1);
  --input: hsla(168, 11%, 26%, 1);
  --ring: hsla(170, 100%, 16%, 1);

  --success: hsla(160, 70%, 45%, 1);
  --success-foreground: #ffffff;
  --success-tint: hsla(160, 30%, 12%, 1);
  --warning: hsla(38, 90%, 55%, 1);
  --warning-foreground: #ffffff;
  --warning-tint: hsla(38, 30%, 14%, 1);

  /* Link & Interactive Inks (Mint 300 - 10:1 AAA on dark pine) */
  --link: hsla(166, 50%, 75%, 1);
  --link-hover: hsla(166, 60%, 88%, 1);
  --link-decoration: hsla(166, 50%, 75%, 0.4);

  --emblem: hsla(356, 86%, 88%, 1); /* Luminous Blush */

  --chart-1: hsla(170, 100%, 16%, 1);
  --chart-2: hsla(354, 34%, 43%, 1);
  --chart-3: hsla(166, 33%, 65%, 1);
  --chart-4: hsla(355, 73%, 79%, 1);
  --chart-5: hsla(164, 48%, 77%, 1);

  --sidebar: hsla(173, 18%, 10%, 1);
  --sidebar-foreground: hsla(0, 0%, 95%, 1);
  --sidebar-primary: hsla(170, 100%, 16%, 1);
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: hsla(170, 13%, 18%, 1);
  --sidebar-accent-foreground: hsla(0, 0%, 95%, 1);
  --sidebar-border: hsla(168, 11%, 26%, 1);
  --sidebar-ring: hsla(170, 100%, 16%, 1);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }

  body {
    @apply bg-background text-foreground;
  }
}

/* -------------------------------------------------------------
 * Theme Presets / Project Personalities
 * Activate with data-theme-variant="blush" | "sharp" | "round"
 * ----------------------------------------------------------- */

/* Preset 1: Blush / Cashmere Petal (Soft, Luminous & Editorial — Pure Blush Scale, Zero Pine) */
[data-theme-variant="blush"],
.theme-blush {
  --radius: 0.875rem; /* 14px soft curve */
  --primary: hsla(356, 86%, 89%, 1); /* Cashmere blush pink #FBC8CB / #FCD3D6 */
  --primary-foreground: hsla(352, 60%, 7%, 1); /* Deep velvet wine noir ink #1d070a (12.7:1 AAA) */
  --primary-hover: hsla(356, 85%, 82%, 1); /* Silky rose petal pink #F8A8B0 */
  --ring: hsla(356, 75%, 65%, 1);
  --accent: hsla(355, 73%, 79%, 1); /* Luminous rose petal accent #F7A3AB */
  --accent-foreground: hsla(352, 60%, 7%, 1);
  --accent-hover: hsla(356, 86%, 88%, 1);

  /* Typography in Blush Light Mode: Deep Velvet Wine Noir */
  --foreground: hsla(352, 60%, 7%, 1); /* Deep Wine Noir #1d070a */
  --card-foreground: hsla(352, 60%, 7%, 1);
  --popover-foreground: hsla(352, 60%, 7%, 1);

  /* Surfaces in Blush Light Mode: Delicate Petal Wash */
  --secondary: hsla(356, 60%, 96%, 1); /* Soft petal wash */
  --secondary-foreground: hsla(352, 60%, 7%, 1);
  --muted: hsla(356, 60%, 96%, 1);
  --muted-foreground: hsla(354, 25%, 45%, 1); /* Dusty rose neutral */
  --border: hsla(355, 40%, 88%, 1); /* Soft rose border */
  --line: hsla(355, 40%, 92%, 1);
  --line-strong: hsla(355, 30%, 80%, 1);
  --control: hsla(355, 25%, 68%, 1);
  --input: hsla(355, 40%, 88%, 1);
  --sidebar: hsla(356, 89%, 96%, 1); /* Soft blush sidebar */
  --sidebar-foreground: hsla(352, 60%, 7%, 1);
  --sidebar-border: hsla(355, 40%, 88%, 1);
  --sidebar-primary: hsla(356, 86%, 89%, 1); /* Cashmere blush #FCD3D6 */
  --sidebar-primary-foreground: hsla(352, 60%, 7%, 1);
  --sidebar-accent: hsla(356, 60%, 92%, 1);
  --sidebar-accent-foreground: hsla(352, 60%, 7%, 1);
  --sidebar-ring: hsla(356, 75%, 65%, 1);

  /* Link & Interactive Inks in Blush Light Mode: Deep Crimson & Velvet Wine (10:1 AAA on white/card) */
  --link: hsla(354, 60%, 32%, 1); /* Deep Crimson #822129 */
  --link-hover: hsla(352, 100%, 13%, 1); /* Deep Wine #420006 */
  --link-decoration: hsla(355, 47%, 68%, 0.8); /* Crisp Rose #dc858b */

  /* Floral Emblem in Blush Light Mode: Darker Shade of Pink (Crimson 500 #93484f, 6.1:1 AAA on light) */
  --emblem: hsla(354, 34%, 43%, 1);
}

[data-theme-variant="blush"] [data-slot="button"][data-variant="default"],
.theme-blush [data-slot="button"][data-variant="default"] {
  border: 1px solid hsla(355, 47%, 68%, 0.6);
  box-shadow: 0 1px 2px rgba(29, 7, 10, 0.05), 0 3px 12px -2px rgba(251, 200, 203, 0.6);
}

/* Link Button in Blush Light Mode: High-contrast Crimson/Wine Ink (10:1 AAA) */
[data-theme-variant="blush"] [data-slot="button"][data-variant="link"],
.theme-blush [data-slot="button"][data-variant="link"] {
  color: hsla(354, 60%, 32%, 1); /* Deep Crimson #822129 */
  text-decoration-color: hsla(355, 47%, 68%, 0.8);
}
[data-theme-variant="blush"] [data-slot="button"][data-variant="link"]:hover,
.theme-blush [data-slot="button"][data-variant="link"]:hover {
  color: hsla(352, 100%, 13%, 1); /* Deep Wine #420006 */
  text-decoration-color: currentColor;
}

/* Editorial button in Blush Light Mode: Deep Wine & Rose Outline (Bookplate Badge) */
[data-theme-variant="blush"] [data-slot="button"][data-variant="editorial"],
.theme-blush [data-slot="button"][data-variant="editorial"] {
  background-color: hsla(356, 89%, 96%, 0.35);
  color: hsla(352, 70%, 22%, 1); /* Deep wine #601119 */
  border: 1px solid hsla(355, 47%, 68%, 0.75); /* Crisp rose border #dc858b */
  box-shadow: 0 1px 2px rgba(96, 17, 25, 0.04);
}

[data-theme-variant="blush"] [data-slot="button"][data-variant="editorial"]:hover,
.theme-blush [data-slot="button"][data-variant="editorial"]:hover {
  background-color: hsla(356, 86%, 88%, 0.45);
  border-color: hsla(354, 34%, 43%, 0.9);
  color: hsla(352, 100%, 13%, 1); /* Deepest wine #420006 */
}

[data-theme-variant="blush"] [data-slot="button"][data-variant="editorial"]:active,
.theme-blush [data-slot="button"][data-variant="editorial"]:active {
  background-color: hsla(356, 86%, 88%, 0.65);
}

/* Detached Explore Sheet Panel in Blush Light Mode */
[data-theme-variant="blush"] .explore-sheet-panel,
.theme-blush .explore-sheet-panel {
  background-color: hsla(356, 89%, 98%, 0.96);
  border-color: hsla(355, 40%, 88%, 0.9);
  box-shadow: 0 20px 50px -10px rgba(29, 7, 10, 0.12), 0 0 0 1px hsla(355, 40%, 88%, 0.6);
}

.dark[data-theme-variant="blush"],
.dark [data-theme-variant="blush"],
.dark .theme-blush,
[data-theme-variant="blush"] .dark,
.theme-blush .dark {
  /* Surfaces in Blush Dark Mode: Midnight Berry & Velvet Plum Scale */
  --background: hsla(352, 55%, 6.5%, 1); /* Midnight Berry Canvas #1a0709 */
  --foreground: hsla(356, 86%, 96%, 1); /* Luminous Petal White #feeced */

  --card: hsla(352, 42%, 11%, 1); /* Deep Plum Card Surface #281013 */
  --card-foreground: hsla(356, 86%, 96%, 1);

  --popover: hsla(352, 42%, 11%, 1);
  --popover-foreground: hsla(356, 86%, 96%, 1);

  --primary: hsla(356, 86%, 89%, 1); /* Luminous blush #FCD3D6 */
  --primary-foreground: hsla(352, 60%, 7%, 1); /* Deep velvet wine noir ink #1d070a */
  --primary-hover: hsla(356, 90%, 94%, 1);

  --secondary: hsla(352, 22%, 18%, 1); /* Dark dusty mauve/berry #382426 */
  --secondary-foreground: hsla(356, 86%, 96%, 1);

  --muted: hsla(352, 22%, 18%, 1);
  --muted-foreground: hsla(352, 20%, 65%, 1); /* Warm dusty rose #b89499 */

  --accent: hsla(355, 73%, 79%, 1); /* Luminous rose secondary #f79da5 */
  --accent-foreground: hsla(352, 60%, 7%, 1);
  --accent-hover: hsla(356, 86%, 88%, 1);

  --border: hsla(352, 20%, 26%, 1); /* Deep berry border #503539 */
  --line: hsla(352, 25%, 16%, 1);
  --line-strong: hsla(352, 20%, 26%, 1);
  --control: hsla(352, 18%, 38%, 1);
  --input: hsla(352, 20%, 26%, 1);
  --ring: hsla(356, 86%, 70%, 1);

  --sidebar: hsla(352, 45%, 9%, 1); /* Deep night berry sidebar #210c10 */
  --sidebar-foreground: hsla(356, 86%, 96%, 1);
  --sidebar-border: hsla(352, 20%, 26%, 1);
  --sidebar-primary: hsla(356, 86%, 89%, 1);
  --sidebar-primary-foreground: hsla(352, 60%, 7%, 1);
  --sidebar-accent: hsla(352, 22%, 18%, 1);
  --sidebar-accent-foreground: hsla(356, 86%, 96%, 1);
  --sidebar-ring: hsla(356, 86%, 70%, 1);

  /* Link & Interactive Inks in Blush Dark Mode: Luminous Rose & Cashmere White (11.5:1 AAA on midnight berry) */
  --link: hsla(356, 86%, 85%, 1); /* Luminous Rose #fcd3d6 */
  --link-hover: hsla(356, 90%, 94%, 1); /* Cashmere White #feeced */
  --link-decoration: hsla(356, 86%, 85%, 0.4);

  /* Floral Emblem in Blush Dark Mode: Luminous Blush (#FCD3D6, 11:1 AAA on midnight berry) */
  --emblem: hsla(356, 86%, 88%, 1);
}

.dark[data-theme-variant="blush"] [data-slot="button"][data-variant="default"],
.dark [data-theme-variant="blush"] [data-slot="button"][data-variant="default"],
.dark .theme-blush [data-slot="button"][data-variant="default"] {
  border: 1px solid hsla(356, 86%, 88%, 0.35);
  box-shadow: 0 0 16px -2px rgba(252, 211, 214, 0.3), 0 2px 4px rgba(0, 0, 0, 0.4);
}

/* Link Button in Blush Dark Mode: Luminous Rose Ink (11.5:1 AAA) */
.dark[data-theme-variant="blush"] [data-slot="button"][data-variant="link"],
.dark [data-theme-variant="blush"] [data-slot="button"][data-variant="link"],
.dark .theme-blush [data-slot="button"][data-variant="link"],
[data-theme-variant="blush"] .dark [data-slot="button"][data-variant="link"],
.theme-blush .dark [data-slot="button"][data-variant="link"] {
  color: hsla(356, 86%, 85%, 1); /* Luminous Rose #fcd3d6 */
  text-decoration-color: hsla(356, 86%, 85%, 0.4);
}

.dark[data-theme-variant="blush"] [data-slot="button"][data-variant="link"]:hover,
.dark [data-theme-variant="blush"] [data-slot="button"][data-variant="link"]:hover,
.dark .theme-blush [data-slot="button"][data-variant="link"]:hover,
[data-theme-variant="blush"] .dark [data-slot="button"][data-variant="link"]:hover,
.theme-blush .dark [data-slot="button"][data-variant="link"]:hover {
  color: hsla(356, 90%, 94%, 1);
  text-decoration-color: currentColor;
}

/* Editorial button in Blush Dark Mode: Refined Luminous Outline */
.dark[data-theme-variant="blush"] [data-slot="button"][data-variant="editorial"],
.dark [data-theme-variant="blush"] [data-slot="button"][data-variant="editorial"],
.dark .theme-blush [data-slot="button"][data-variant="editorial"] {
  background-color: hsla(352, 42%, 11%, 0.35);
  color: hsla(356, 86%, 88%, 1); /* Luminous blush text #fcd3d6 */
  border: 1px solid hsla(355, 47%, 68%, 0.35);
  box-shadow: none;
}

.dark[data-theme-variant="blush"] [data-slot="button"][data-variant="editorial"]:hover,
.dark [data-theme-variant="blush"] [data-slot="button"][data-variant="editorial"]:hover,
.dark .theme-blush [data-slot="button"][data-variant="editorial"]:hover {
  background-color: hsla(352, 42%, 11%, 0.7);
  border-color: hsla(355, 73%, 79%, 0.6);
  color: hsla(356, 90%, 94%, 1);
}

.dark[data-theme-variant="blush"] [data-slot="button"][data-variant="editorial"]:active,
.dark [data-theme-variant="blush"] [data-slot="button"][data-variant="editorial"]:active,
.dark .theme-blush [data-slot="button"][data-variant="editorial"]:active {
  background-color: hsla(352, 22%, 18%, 0.6);
}

/* Detached Explore Sheet Panel in Blush Dark Mode */
.dark[data-theme-variant="blush"] .explore-sheet-panel,
.dark [data-theme-variant="blush"] .explore-sheet-panel,
.dark .theme-blush .explore-sheet-panel,
[data-theme-variant="blush"] .dark .explore-sheet-panel,
.theme-blush .dark .explore-sheet-panel {
  background-color: hsla(352, 45%, 9%, 0.96); /* Deep Night Berry #210c10 */
  border-color: hsla(352, 20%, 26%, 0.85); /* Deep Berry #503539 */
  box-shadow: 0 24px 60px -12px rgba(0, 0, 0, 0.7), 0 0 0 1px hsla(356, 86%, 85%, 0.15);
}

/* Floral Emblem in Blush Theme (Enforces darker shade of pink in light mode) */
[data-theme-variant="blush"] [data-slot="brand-flower"],
.theme-blush [data-slot="brand-flower"],
[data-theme-variant="blush"] .floral-emblem,
.theme-blush .floral-emblem {
  color: var(--emblem);
}

.dark[data-theme-variant="blush"] [data-slot="brand-flower"],
.dark [data-theme-variant="blush"] [data-slot="brand-flower"],
.dark .theme-blush [data-slot="brand-flower"],
[data-theme-variant="blush"] .dark [data-slot="brand-flower"],
.theme-blush .dark [data-slot="brand-flower"] {
  color: var(--emblem);
}

/* Standard Inline Text Link */
.inline-link,
a.inline-link {
  color: var(--link);
  text-decoration: underline;
  text-underline-offset: 4px;
  text-decoration-color: var(--link-decoration);
  transition: color 150ms ease-out, text-decoration-color 150ms ease-out;
}
.inline-link:hover,
a.inline-link:hover {
  color: var(--link-hover);
  text-decoration-color: currentColor;
}

/* Preset 2: Sharp Technical (Razor-sharp 2px corners) */
[data-theme-variant="sharp"],
.theme-sharp {
  --radius: 2px;
}

/* Preset 3: Extra Round / Pebble (Pill-like Organic 18px) */
[data-theme-variant="round"],
.theme-round {
  --radius: 1.125rem; /* 18px */
}
